using System;
using System.IO;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using DualDiscord;
static class VencordSharingTests {
 static int total,failed;static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static void Assert(bool value){if(!value)throw new Exception("Assertion failed");}
 static void Check(string name,Action test){total++;try{test();Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
 static string Fixture(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"VencordCopy-"+Guid.NewGuid().ToString("N"));foreach(string profile in new[]{"main","second"})Directory.CreateDirectory(Path.Combine(path,profile,"settings"));File.WriteAllText(Path.Combine(path,"main","settings","settings.json"),"{\"plugins\":{\"Example\":{\"enabled\":true,\"size\":14,\"apiKey\":\"source-secret\",\"nested\":{\"token\":\"secret\",\"color\":\"blue\"}}},\"cloud\":{\"authenticated\":true},\"nativeTitleBar\":true,\"enabledThemes\":[\"one.css\"],\"useQuickCss\":true}");File.WriteAllText(Path.Combine(path,"second","settings","settings.json"),"{\"plugins\":{\"Example\":{\"enabled\":false,\"size\":9,\"apiKey\":\"own-key\",\"nested\":{\"token\":\"own-token\"}}},\"cloud\":{\"authenticated\":false},\"untouched\":42}");return path;}
 static Dictionary<string,object> Read(string path){return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(path,"second","settings","settings.json")));}
 static Dictionary<string,object> Plugin(Dictionary<string,object> root){return (Dictionary<string,object>)((Dictionary<string,object>)root["plugins"])["Example"];}
 static void Apply(string path,Customization options){VencordSharing.Apply(Path.Combine(path,"main"),Path.Combine(path,"second"),options);}
 static void Reject(Action action){try{action();}catch(IOException){return;}throw new Exception("Expected safe rejection");}
 public static int Run(){
  Check("Vencord categories default off",()=>{var o=new Customization();Assert(!o.CopyVencordPlugins&&!o.CopyVencordPluginSettings&&!o.CopyVencordPreferences&&!o.CopyVencordAppearance&&!o.CopyQuickCss);});
  Check("Plugin enablement copies without replacing plugin options or cloud",()=>{string p=Fixture();Apply(p,new Customization{CopyVencordPlugins=true});var value=Read(p);var plugin=Plugin(value);Assert((bool)plugin["enabled"]&&(int)plugin["size"]==9&&!(bool)((Dictionary<string,object>)value["cloud"])["authenticated"]&&(int)value["untouched"]==42);});
  Check("Plugin options preserve second credentials and enabled states",()=>{string p=Fixture();Apply(p,new Customization{CopyVencordPluginSettings=true});var plugin=Plugin(Read(p));var nested=(Dictionary<string,object>)plugin["nested"];Assert(!(bool)plugin["enabled"]&&(int)plugin["size"]==14&&(string)plugin["apiKey"]=="own-key"&&(string)nested["token"]=="own-token"&&(string)nested["color"]=="blue");});
  Check("General Vencord preferences exclude cloud and theme choices",()=>{string p=Fixture();Apply(p,new Customization{CopyVencordPreferences=true});var value=Read(p);Assert((bool)value["nativeTitleBar"]&&!value.ContainsKey("enabledThemes")&&!(bool)((Dictionary<string,object>)value["cloud"])["authenticated"]);});
  Check("Theme choices and QuickCSS can be copied independently",()=>{string p=Fixture();File.WriteAllText(Path.Combine(p,"main","settings","quickCss.css"),"new-css");File.WriteAllText(Path.Combine(p,"second","settings","quickCss.css"),"old-css");Apply(p,new Customization{CopyVencordAppearance=true,CopyQuickCss=true});var value=Read(p);Assert(value.ContainsKey("enabledThemes")&&(bool)value["useQuickCss"]&&File.ReadAllText(Path.Combine(p,"second","settings","quickCss.css"))=="new-css"&&Directory.GetFiles(Path.Combine(p,"second","Backups"),"quickCss.css",SearchOption.AllDirectories).Length==1);});
  Check("Vencord copy backs up replacements and never changes main",()=>{string p=Fixture();string file=Path.Combine(p,"main","settings","settings.json"),original=File.ReadAllText(file);Apply(p,new Customization{CopyVencordPlugins=true});Assert(File.ReadAllText(file)==original&&Directory.GetFiles(Path.Combine(p,"second","Backups"),"settings.json",SearchOption.AllDirectories).Length==1);});
  Check("Same Vencord folder cannot be copied onto itself",()=>{string p=Fixture();Reject(()=>VencordSharing.Apply(Path.Combine(p,"main"),Path.Combine(p,"main"),new Customization{CopyVencordPlugins=true}));});
  Check("Malformed main settings leave second unchanged",()=>{string p=Fixture();string file=Path.Combine(p,"second","settings","settings.json"),before=File.ReadAllText(file);File.WriteAllText(Path.Combine(p,"main","settings","settings.json"),"broken");Reject(()=>Apply(p,new Customization{CopyVencordPlugins=true}));Assert(File.ReadAllText(file)==before);});
  Check("Disabled copying does not touch settings or create backups",()=>{string p=Fixture();Apply(p,new Customization());Assert(!Directory.Exists(Path.Combine(p,"second","Backups")));});
  Check("Unchanged Vencord settings do not create repeated backups",()=>{string p=Fixture();var o=new Customization{CopyVencordPlugins=true};Apply(p,o);Apply(p,o);Assert(Directory.GetDirectories(Path.Combine(p,"second","Backups")).Length==1);});
  Check("Oversized Vencord input leaves second unchanged",()=>{string p=Fixture();string file=Path.Combine(p,"second","settings","settings.json"),before=File.ReadAllText(file);File.WriteAllText(Path.Combine(p,"main","settings","settings.json"),new string('x',4*1024*1024+1));Reject(()=>Apply(p,new Customization{CopyVencordPlugins=true}));Assert(File.ReadAllText(file)==before);});
  Check("Linked Vencord backups cannot redirect replacement writes",()=>{string p=Fixture();string outside=Path.Combine(p,"outside");Directory.CreateDirectory(outside);using(var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("cmd.exe","/c mklink /J \""+Path.Combine(p,"second","Backups")+"\" \""+outside+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true})){process.StandardOutput.ReadToEnd();process.WaitForExit();Assert(process.ExitCode==0);}string before=File.ReadAllText(Path.Combine(p,"second","settings","settings.json"));Reject(()=>Apply(p,new Customization{CopyVencordPlugins=true}));Assert(Directory.GetFileSystemEntries(outside).Length==0&&File.ReadAllText(Path.Combine(p,"second","settings","settings.json"))==before);});
  Console.WriteLine("VENCORD "+(total-failed)+" passed, "+failed+" failed");return failed;
 }
}
